<?php
function main() {
    $input = file_exists("input.txt") ? file("input.txt", FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) : [];
    if (empty($input)) {
        $input = [fgets(STDIN)];
    }
    $lineIndex = 0;

    $n = intval($input[$lineIndex++]);
    $k = intval($input[$lineIndex++]);
    $s = $input[$lineIndex++];
    $s = str_split($s);

    $used = array_fill(0, $n, false);

    $gPos = array_search('G', $s);

    function dfs($u, $k, $s, &$used, $n) {
        if ($u < 0 || $u >= $n || $used[$u] || $s[$u] === '#') {
            return false;
        }
        if ($s[$u] === 'T') {
            return true;
        }
        $used[$u] = true;
        return dfs($u - $k, $k, $s, $used, $n) || dfs($u + $k, $k, $s, $used, $n);
    }

    $result = dfs($gPos, $k, $s, $used, $n);
    echo $result ? "YES" : "NO";
}

main();
